{
  "type": "RemoteMCPServer",
  "remoteMCPServer": {
    "apiVersion": "kagent.dev/v1alpha2",
    "kind": "RemoteMCPServer",
    "metadata": {
      "name": "fetch-via-api",
      "namespace": "{{ns}}"
    },
    "spec": {
      "description": "The kmcp-run fetch server, registered a second time through the API",
      "protocol": "STREAMABLE_HTTP",
      "url": "http://fetch.kagent:3000/mcp",
      "timeout": "30s"
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": 6,
  "method": "tools/call",
  "params": {
    "name": "k8s_get_pod_logs",
    "arguments": {
      "pod_name": "<a worker pod name from the pods call>",
      "namespace": "demo-broken",
      "tail_lines": 20
    }
  }
}

{
  "apiVersion": "kagent.dev/v1alpha2",
  "kind": "Agent",
  "metadata": {
    "name": "node-reporter",
    "namespace": "{{ns}}"
  },
  "spec": {
    "description": "Created through the controller API instead of kubectl. Reports on nodes only.",
    "type": "Declarative",
    "declarative": {
      "modelConfig": "default-model-config",
      "systemMessage": "You report on the nodes of this cluster. Use k8s_get_resources with resource_type nodes and output wide, then k8s_describe_resource for details. Answer only from tool results.",
      "tools": [
        {
          "type": "McpServer",
          "mcpServer": {
            "apiGroup": "kagent.dev",
            "kind": "RemoteMCPServer",
            "name": "kagent-tool-server",
            "toolNames": [
              "k8s_get_resources",
              "k8s_describe_resource"
            ]
          }
        }
      ]
    }
  }
}

{
  "apiVersion": "kagent.dev/v1alpha2",
  "kind": "Agent",
  "metadata": {
    "name": "node-reporter",
    "namespace": "{{ns}}"
  },
  "spec": {
    "description": "Updated through the API",
    "type": "Declarative",
    "declarative": {
      "modelConfig": "default-model-config",
      "systemMessage": "You report on the nodes of this cluster. Use k8s_get_resources with resource_type nodes and output wide, then k8s_describe_resource for details. Answer only from tool results.",
      "tools": [
        {
          "type": "McpServer",
          "mcpServer": {
            "apiGroup": "kagent.dev",
            "kind": "RemoteMCPServer",
            "name": "kagent-tool-server",
            "toolNames": [
              "k8s_get_resources",
              "k8s_describe_resource"
            ]
          }
        }
      ]
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": "1",
  "method": "message/send",
  "params": {
    "message": {
      "role": "user",
      "kind": "message",
      "messageId": "{{$guid}}",
      "parts": [
        {
          "kind": "text",
          "text": "Which pods in namespace demo-broken are not Running, and why? One line per pod."
        }
      ]
    }
  }
}

{
